def L(file, id, title, std, comp, salt, t, term, kcal, b, f, cap='Про рибу', **kw):
    d = dict(file=file, id=id, title=title, std=std, comp=comp, salt=salt, t=t, term=term, kcal=kcal, b=b, f=f, cap=cap)
    d.update(kw)
    return d


